import Foundation

/// Personal context generated by tools/build_context.py (repos, servers, terminal shortcuts, links).
/// Read-only for the app; ~/Library/Application Support/OptHelper/context.json
struct PersonalContext: Codable {
    struct GitHub: Codable {
        struct Repo: Codable { var name: String; var description: String }
        var org: String
        var user: String?
        var url_patterns: [String: String]
        var repos: [Repo]
    }
    struct Shortcut: Codable {
        var name: String
        var does: String
        var command: String?     // present only if the launcher may run it
        var forward: Bool?
        var port_args: Bool?
        var confirm: Bool?
        var cwd: String?
    }
    struct Server: Codable { var name: String; var vm: String?; var cloud: String?; var host: String?; var note: String? }
    struct Link: Codable { var name: String; var url: String }

    var github: GitHub?
    var projects_root: String?
    var editor: String?
    var terminal_shortcuts: [Shortcut]?
    var servers: [Server]?
    var links: [Link]?
    var safari_profiles: [String]?
}

enum ContextStore {
    static var url: URL { Memory.shared.url.deletingLastPathComponent().appendingPathComponent("context.json") }

    static func load() -> PersonalContext? {
        guard let d = try? Data(contentsOf: url) else { return nil }
        return try? JSONDecoder().decode(PersonalContext.self, from: d)
    }

    static var projectsRoot: URL {
        let p = load()?.projects_root ?? NSHomeDirectory() + "/Desktop"
        return URL(fileURLWithPath: p).resolvingSymlinksInPath()
    }

    static var editor: String { load()?.editor ?? "Visual Studio Code" }

    /// Compact text block for the model prompt.
    static func promptBlock() -> String {
        guard let c = load() else { return "" }
        var s = ""
        if let g = c.github {
            s += "GitHub org \"\(g.org)\" (user \(g.user ?? "?")). URL patterns:\n"
            for (k, v) in g.url_patterns.sorted(by: { $0.key < $1.key }) { s += "  \(k): \(v)\n" }
            s += "Repos (name — description):\n"
            for r in g.repos { s += "  \(r.name)" + (r.description.isEmpty ? "" : " — \(r.description)") + "\n" }
        }
        if let t = c.terminal_shortcuts, !t.isEmpty {
            s += "Terminal shortcuts (run with run_shortcut by name; ones marked [no-run] are context only):\n" + t.map { "  \($0.name)\($0.command == nil ? " [no-run]" : ""): \($0.does)" }.joined(separator: "\n") + "\n"
        }
        if let sv = c.servers, !sv.isEmpty, let d = try? JSONEncoder().encode(sv), let j = String(data: d, encoding: .utf8) {
            s += "Servers: \(j)\n"
        }
        if let sp = c.safari_profiles, !sp.isEmpty { s += "Safari profiles: \(sp.joined(separator: ", "))\n" }
        if let l = c.links, !l.isEmpty {
            s += "Saved links:\n" + l.map { "  \($0.name): \($0.url)" }.joined(separator: "\n") + "\n"
        }
        let root = projectsRoot
        let dirs = ((try? FileManager.default.contentsOfDirectory(atPath: root.path)) ?? []).filter { name in
            var isDir: ObjCBool = false
            return !name.hasPrefix(".") && FileManager.default.fileExists(atPath: root.appendingPathComponent(name).path, isDirectory: &isDir) && isDir.boolValue
        }.sorted()
        s += "Project folders under \(root.path) (open with open_folder, editor default \(editor)):\n  " + dirs.joined(separator: ", ") + "\n"
        return s
    }
}

enum FolderSearch {
    private static func key(_ s: String) -> String { s.lowercased().filter { $0.isLetter || $0.isNumber } }

    /// Resolves a model-supplied path or bare folder name to a real directory INSIDE the projects root.
    /// Anything outside the root is refused.
    static func resolve(_ input: String) -> URL? {
        let root = ContextStore.projectsRoot
        let fm = FileManager.default
        func isDir(_ u: URL) -> Bool { var d: ObjCBool = false; return fm.fileExists(atPath: u.path, isDirectory: &d) && d.boolValue }
        func inside(_ u: URL) -> Bool { u.path == root.path || u.path.hasPrefix(root.path + "/") }

        if input.hasPrefix("/") || input.hasPrefix("~") {
            let u = URL(fileURLWithPath: (input as NSString).expandingTildeInPath).resolvingSymlinksInPath()
            if inside(u), isDir(u) { return u }
        }
        let want = key((input as NSString).lastPathComponent)
        guard !want.isEmpty else { return nil }

        // Breadth-first, up to 3 levels deep; exact name wins over substring match.
        var level = [root], partial: URL?
        for _ in 0..<3 {
            var next: [URL] = []
            for dir in level {
                for name in (try? fm.contentsOfDirectory(atPath: dir.path)) ?? [] {
                    if name.hasPrefix(".") || name == "node_modules" { continue }
                    let u = dir.appendingPathComponent(name).resolvingSymlinksInPath()
                    guard inside(u), isDir(u) else { continue }
                    let k = key(name)
                    if k == want { return u }
                    if partial == nil, k.contains(want) || want.contains(k) && k.count > 3 { partial = u }
                    next.append(u)
                }
            }
            level = next
        }
        return partial
    }
}
